
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;
SET UNIQUE_CHECKS = 1;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO,STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION';

-- -----------------------------------------------------------------------------
-- Base de données
-- -----------------------------------------------------------------------------
CREATE DATABASE IF NOT EXISTS `trackit` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `trackit`;

-- -----------------------------------------------------------------------------
-- Suppression des tables existantes (ordre inverse des dépendances)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `flyway_schema_history`;
DROP TABLE IF EXISTS `paiement`;
DROP TABLE IF EXISTS `abonnement`;
DROP TABLE IF EXISTS `rapport`;
DROP TABLE IF EXISTS `notification`;
DROP TABLE IF EXISTS `piece_jointe`;
DROP TABLE IF EXISTS `historique`;
DROP TABLE IF EXISTS `commentaire`;
DROP TABLE IF EXISTS `anomalie`;
DROP TABLE IF EXISTS `systeme_it`;
DROP TABLE IF EXISTS `utilisateur`;
DROP TABLE IF EXISTS `organisation`;
DROP TABLE IF EXISTS `type_anomalie`;
DROP TABLE IF EXISTS `priorite`;
DROP TABLE IF EXISTS `statut`;
DROP TABLE IF EXISTS `role`;

-- -----------------------------------------------------------------------------
-- Création des tables (PK, FK, UNIQUE, INDEX, CHECK, DEFAULT déclarés dans chaque table)
-- -----------------------------------------------------------------------------

-- Table `role`
CREATE TABLE `role` (
  `id_role` bigint NOT NULL AUTO_INCREMENT,
  `nom` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_role`),
  UNIQUE KEY `uk_role_nom` (`nom`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `statut`
CREATE TABLE `statut` (
  `id_statut` bigint NOT NULL AUTO_INCREMENT,
  `nom` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_statut`),
  UNIQUE KEY `uk_statut_nom` (`nom`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `priorite`
CREATE TABLE `priorite` (
  `id_priorite` bigint NOT NULL AUTO_INCREMENT,
  `nom` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `niveau` int NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_priorite`),
  UNIQUE KEY `uk_priorite_nom` (`nom`),
  CONSTRAINT `ck_priorite_niveau` CHECK ((`niveau` between 1 and 4))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `type_anomalie`
CREATE TABLE `type_anomalie` (
  `id_type` bigint NOT NULL AUTO_INCREMENT,
  `nom` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_type`),
  UNIQUE KEY `uk_type_anomalie_nom` (`nom`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `organisation`
CREATE TABLE `organisation` (
  `id_organisation` bigint NOT NULL AUTO_INCREMENT,
  `nom` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_creation` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_organisation`),
  UNIQUE KEY `uk_organisation_email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `utilisateur`
CREATE TABLE `utilisateur` (
  `id_utilisateur` bigint NOT NULL AUTO_INCREMENT,
  `nom` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `prenom` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mot_de_passe` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `actif` tinyint(1) NOT NULL DEFAULT '1',
  `date_creation` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_role` bigint NOT NULL,
  `id_organisation` bigint NOT NULL,
  PRIMARY KEY (`id_utilisateur`),
  UNIQUE KEY `uk_utilisateur_email` (`email`),
  KEY `idx_utilisateur_role` (`id_role`),
  KEY `idx_utilisateur_organisation` (`id_organisation`),
  CONSTRAINT `fk_utilisateur_organisation` FOREIGN KEY (`id_organisation`) REFERENCES `organisation` (`id_organisation`),
  CONSTRAINT `fk_utilisateur_role` FOREIGN KEY (`id_role`) REFERENCES `role` (`id_role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `systeme_it`
CREATE TABLE `systeme_it` (
  `id_systeme` bigint NOT NULL AUTO_INCREMENT,
  `nom` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `adresse` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `actif` tinyint(1) NOT NULL DEFAULT '1',
  `id_organisation` bigint NOT NULL,
  PRIMARY KEY (`id_systeme`),
  UNIQUE KEY `uk_systeme_it_nom_organisation` (`id_organisation`,`nom`),
  CONSTRAINT `fk_systeme_it_organisation` FOREIGN KEY (`id_organisation`) REFERENCES `organisation` (`id_organisation`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `anomalie`
CREATE TABLE `anomalie` (
  `id_anomalie` bigint NOT NULL AUTO_INCREMENT,
  `titre` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_creation` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `date_resolution` datetime DEFAULT NULL,
  `id_auteur` bigint NOT NULL,
  `id_operateur` bigint DEFAULT NULL,
  `id_systeme` bigint NOT NULL,
  `id_type` bigint NOT NULL,
  `id_priorite` bigint NOT NULL,
  `id_statut` bigint NOT NULL,
  PRIMARY KEY (`id_anomalie`),
  KEY `idx_anomalie_auteur` (`id_auteur`),
  KEY `idx_anomalie_operateur` (`id_operateur`),
  KEY `idx_anomalie_systeme` (`id_systeme`),
  KEY `idx_anomalie_type` (`id_type`),
  KEY `idx_anomalie_priorite` (`id_priorite`),
  KEY `idx_anomalie_statut` (`id_statut`),
  KEY `idx_anomalie_date_creation` (`date_creation`),
  KEY `idx_anomalie_date_resolution` (`date_resolution`),
  CONSTRAINT `fk_anomalie_auteur` FOREIGN KEY (`id_auteur`) REFERENCES `utilisateur` (`id_utilisateur`),
  CONSTRAINT `fk_anomalie_operateur` FOREIGN KEY (`id_operateur`) REFERENCES `utilisateur` (`id_utilisateur`),
  CONSTRAINT `fk_anomalie_priorite` FOREIGN KEY (`id_priorite`) REFERENCES `priorite` (`id_priorite`),
  CONSTRAINT `fk_anomalie_statut` FOREIGN KEY (`id_statut`) REFERENCES `statut` (`id_statut`),
  CONSTRAINT `fk_anomalie_systeme` FOREIGN KEY (`id_systeme`) REFERENCES `systeme_it` (`id_systeme`),
  CONSTRAINT `fk_anomalie_type` FOREIGN KEY (`id_type`) REFERENCES `type_anomalie` (`id_type`),
  CONSTRAINT `ck_anomalie_dates` CHECK (((`date_resolution` is null) or (`date_resolution` >= `date_creation`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `commentaire`
CREATE TABLE `commentaire` (
  `id_commentaire` bigint NOT NULL AUTO_INCREMENT,
  `contenu` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_creation` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_anomalie` bigint NOT NULL,
  `id_utilisateur` bigint NOT NULL,
  PRIMARY KEY (`id_commentaire`),
  KEY `idx_commentaire_anomalie` (`id_anomalie`),
  KEY `idx_commentaire_utilisateur` (`id_utilisateur`),
  CONSTRAINT `fk_commentaire_anomalie` FOREIGN KEY (`id_anomalie`) REFERENCES `anomalie` (`id_anomalie`) ON DELETE CASCADE,
  CONSTRAINT `fk_commentaire_utilisateur` FOREIGN KEY (`id_utilisateur`) REFERENCES `utilisateur` (`id_utilisateur`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `historique`
CREATE TABLE `historique` (
  `id_historique` bigint NOT NULL AUTO_INCREMENT,
  `action` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ancien_statut` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nouveau_statut` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ancienne_priorite` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nouvelle_priorite` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_modification` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_anomalie` bigint NOT NULL,
  `id_utilisateur` bigint NOT NULL,
  PRIMARY KEY (`id_historique`),
  KEY `idx_historique_anomalie` (`id_anomalie`),
  KEY `idx_historique_utilisateur` (`id_utilisateur`),
  CONSTRAINT `fk_historique_anomalie` FOREIGN KEY (`id_anomalie`) REFERENCES `anomalie` (`id_anomalie`) ON DELETE CASCADE,
  CONSTRAINT `fk_historique_utilisateur` FOREIGN KEY (`id_utilisateur`) REFERENCES `utilisateur` (`id_utilisateur`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `piece_jointe`
CREATE TABLE `piece_jointe` (
  `id_piece_jointe` bigint NOT NULL AUTO_INCREMENT,
  `nom_fichier` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chemin` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type_fichier` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_ajout` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_anomalie` bigint NOT NULL,
  `id_utilisateur` bigint NOT NULL,
  PRIMARY KEY (`id_piece_jointe`),
  KEY `idx_piece_jointe_anomalie` (`id_anomalie`),
  KEY `idx_piece_jointe_utilisateur` (`id_utilisateur`),
  CONSTRAINT `fk_piece_jointe_anomalie` FOREIGN KEY (`id_anomalie`) REFERENCES `anomalie` (`id_anomalie`) ON DELETE CASCADE,
  CONSTRAINT `fk_piece_jointe_utilisateur` FOREIGN KEY (`id_utilisateur`) REFERENCES `utilisateur` (`id_utilisateur`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `notification`
CREATE TABLE `notification` (
  `id_notification` bigint NOT NULL AUTO_INCREMENT,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_creation` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `lu` tinyint(1) NOT NULL DEFAULT '0',
  `id_utilisateur` bigint NOT NULL,
  `id_anomalie` bigint DEFAULT NULL,
  PRIMARY KEY (`id_notification`),
  KEY `idx_notification_utilisateur_lu` (`id_utilisateur`,`lu`),
  KEY `idx_notification_anomalie` (`id_anomalie`),
  CONSTRAINT `fk_notification_anomalie` FOREIGN KEY (`id_anomalie`) REFERENCES `anomalie` (`id_anomalie`) ON DELETE CASCADE,
  CONSTRAINT `fk_notification_utilisateur` FOREIGN KEY (`id_utilisateur`) REFERENCES `utilisateur` (`id_utilisateur`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `rapport`
CREATE TABLE `rapport` (
  `id_rapport` bigint NOT NULL AUTO_INCREMENT,
  `titre` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `format` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_generation` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `chemin_fichier` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_analyste` bigint NOT NULL,
  PRIMARY KEY (`id_rapport`),
  KEY `idx_rapport_analyste` (`id_analyste`),
  CONSTRAINT `fk_rapport_analyste` FOREIGN KEY (`id_analyste`) REFERENCES `utilisateur` (`id_utilisateur`),
  CONSTRAINT `ck_rapport_format` CHECK ((`format` in (_utf8mb4'PDF',_utf8mb4'EXCEL')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `abonnement`
CREATE TABLE `abonnement` (
  `id_abonnement` bigint NOT NULL AUTO_INCREMENT,
  `offre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_debut` date NOT NULL,
  `date_fin` date DEFAULT NULL,
  `statut` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_organisation` bigint NOT NULL,
  PRIMARY KEY (`id_abonnement`),
  KEY `idx_abonnement_organisation` (`id_organisation`),
  CONSTRAINT `fk_abonnement_organisation` FOREIGN KEY (`id_organisation`) REFERENCES `organisation` (`id_organisation`),
  CONSTRAINT `ck_abonnement_dates` CHECK (((`date_fin` is null) or (`date_fin` >= `date_debut`))),
  CONSTRAINT `ck_abonnement_statut` CHECK ((`statut` in (_utf8mb4'EN_ATTENTE',_utf8mb4'ACTIF',_utf8mb4'EXPIRE',_utf8mb4'ANNULE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `paiement`
CREATE TABLE `paiement` (
  `id_paiement` bigint NOT NULL AUTO_INCREMENT,
  `montant` decimal(10,2) NOT NULL,
  `devise` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_paiement` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `statut` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_stripe` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_abonnement` bigint NOT NULL,
  PRIMARY KEY (`id_paiement`),
  UNIQUE KEY `uk_paiement_reference_stripe` (`reference_stripe`),
  KEY `idx_paiement_abonnement` (`id_abonnement`),
  CONSTRAINT `fk_paiement_abonnement` FOREIGN KEY (`id_abonnement`) REFERENCES `abonnement` (`id_abonnement`),
  CONSTRAINT `ck_paiement_montant` CHECK ((`montant` > 0)),
  CONSTRAINT `ck_paiement_statut` CHECK ((`statut` in (_utf8mb4'EN_ATTENTE',_utf8mb4'REUSSI',_utf8mb4'ECHOUE',_utf8mb4'ANNULE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table `flyway_schema_history`
CREATE TABLE `flyway_schema_history` (
  `installed_rank` int NOT NULL,
  `version` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `script` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `checksum` int DEFAULT NULL,
  `installed_by` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `installed_on` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `execution_time` int NOT NULL,
  `success` tinyint(1) NOT NULL,
  PRIMARY KEY (`installed_rank`),
  KEY `flyway_schema_history_s_idx` (`success`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

