INSERT INTO `anomalie` (`id_anomalie`, `titre`, `description`, `date_creation`, `date_resolution`, `id_auteur`, `id_operateur`, `id_systeme`, `id_type`, `id_priorite`, `id_statut`) VALUES (1,'Doublons de fiches clients – plateau du 3e étage','Des fiches clients sont créées en double lors de l\'import du fichier des partenaires.','2026-04-01 16:30:55','2026-04-10 11:32:55',10,7,17,7,1,4),(2,'Erreur lors de l\'authentification','Message « Votre mot de passe a expiré » affiché en boucle à l\'accueil, même après réinitialisation.','2026-04-01 21:09:13','2026-04-02 19:31:13',12,2,10,4,3,4),(3,'Interruption du réseau interne – bâtiment B','Les utilisateurs au 2e étage perdent l\'accès aux ressources internes par intermittence depuis hier soir.','2026-04-02 09:46:09','2026-04-03 02:02:09',9,6,2,1,3,4),(4,'Requêtes lentes sur la base – direction générale','Le rapport des ventes met plus de 3 minutes à s\'exécuter ; plusieurs requêtes sans index identifiées.','2026-04-02 17:51:14','2026-04-03 19:09:14',11,12,5,5,3,4),(5,'Espace disque insuffisant – plateau du 3e étage','Alerte de supervision : le volume de données est rempli à 96 %. Les écritures risquent d\'échouer.','2026-04-06 08:01:41','2026-04-07 00:47:41',12,10,5,6,3,4),(6,'Erreur de synchronisation','La synchronisation nocturne entre le CRM et l\'ERP a échoué ce matin. Les commandes du jour ne sont pas remontées.','2026-04-07 10:50:23','2026-04-08 22:44:23',2,2,17,2,2,4),(7,'Impossible de se connecter à l\'ERP – 2e étage','Message « Session expirée » à la connexion à l\'ERP pour les utilisateurs à l\'entrepôt. Le problème est apparu ce matin.','2026-04-07 13:46:08','2026-04-07 23:39:08',12,10,1,2,3,4),(8,'Interruption du réseau interne','Les utilisateurs à l\'accueil perdent l\'accès aux ressources internes par intermittence depuis ce matin.','2026-04-07 17:17:48','2026-04-07 22:27:48',11,12,15,1,4,3),(9,'Passerelle API ne répond plus – service commercial','L\'API REST renvoie des erreurs 502 depuis la coupure électrique de ce week-end ; les applications partenaires ne peuvent plus transmettre leurs commandes.','2026-04-09 15:35:11','2026-04-10 16:24:11',2,8,17,2,3,4),(10,'Temps de réponse élevé de l\'application – service comptabilité','Les écrans de saisie mettent plus de 20 secondes à s\'afficher au bâtiment B depuis la mise à jour de la nuit.','2026-04-09 21:30:34','2026-04-10 17:41:34',12,7,17,6,3,4),(11,'Export comptable incomplet','L\'export mensuel des écritures vers le cabinet comptable omet les avoirs.','2026-04-11 09:14:07','2026-04-13 00:29:07',2,8,1,7,2,4),(12,'Indisponibilité du serveur de fichiers','Les partages réseau à l\'agence de Rabat sont inaccessibles depuis la mise à jour de la nuit. Les utilisateurs obtiennent l\'erreur « Chemin réseau introuvable ».','2026-04-13 16:38:13','2026-04-14 02:08:13',10,12,4,1,4,4),(13,'Lenteurs sur le serveur (Base de données Finance)','Le serveur répond très lentement à l\'accueil ; l\'utilisation processeur reste au-dessus de 90 % depuis la mise à jour de la nuit.','2026-04-14 10:55:10','2026-04-16 05:37:10',12,11,5,6,2,4),(14,'Problème d\'accès à la base de données – bâtiment B','Les requêtes échouent avec « Too many connections » depuis midi ; le pool de connexions est saturé.','2026-04-15 07:15:58','2026-04-15 13:39:58',12,9,5,5,4,4),(15,'Erreur de connexion à l\'ERP','Message « Session expirée » à la connexion à l\'ERP pour les utilisateurs à l\'entrepôt. Le problème est apparu ce matin.','2026-04-15 09:17:44','2026-04-15 15:21:44',10,12,1,2,4,4),(16,'Échec de sauvegarde','La sauvegarde complète planifiée la mise à jour de la nuit s\'est arrêtée à 63 % avec l\'erreur « Snapshot creation failed ».','2026-04-15 10:04:45','2026-04-18 04:31:45',6,11,13,8,2,4),(17,'Problème d\'accès à la base de données (Base de données Finance)','Les requêtes échouent avec « Too many connections » depuis l\'ouverture des bureaux ; le pool de connexions est saturé.','2026-04-15 21:48:26',NULL,11,12,5,5,3,2),(18,'Coupure réseau bâtiment A – service achats','Plus aucune connectivité au bâtiment A depuis le redémarrage de lundi. Le commutateur d\'étage ne répond plus.','2026-04-17 15:02:12','2026-04-17 23:37:12',7,12,2,1,4,3),(19,'Interruption du réseau interne','Les utilisateurs à la direction générale perdent l\'accès aux ressources internes par intermittence depuis 8 h 30.','2026-04-17 16:21:18','2026-04-19 06:31:18',10,10,9,1,3,4),(20,'Erreur lors de l\'authentification – site de Tanger','Message « Votre mot de passe a expiré » affiché en boucle à l\'entrepôt, même après réinitialisation.','2026-04-20 08:59:05','2026-04-23 03:21:05',11,7,16,4,2,4),(21,'Doublons de fiches clients (CRM)','Des fiches clients sont créées en double lors de l\'import du fichier des partenaires.','2026-04-20 13:51:18','2026-04-23 23:13:18',2,7,17,7,1,4),(22,'Espace disque insuffisant – service achats','Alerte de supervision : le volume de données est rempli à 96 %. Les écritures risquent d\'échouer.','2026-04-20 22:05:10','2026-04-21 21:19:10',2,12,13,6,3,4),(23,'Coupure réseau bâtiment A – direction générale','Plus aucune connectivité au bâtiment A depuis hier soir. Le commutateur d\'étage ne répond plus.','2026-04-21 08:47:39','2026-04-21 13:24:39',8,6,2,1,4,4),(24,'Volume de données presque saturé','Alerte de supervision : le volume de données est rempli à 96 %. Les écritures risquent d\'échouer.','2026-04-21 11:22:24','2026-04-23 01:12:24',11,12,13,6,2,4),(25,'Fermeture inattendue de l\'écran Mes commandes','L\'application mobile se ferme à l\'ouverture de l\'écran « Mes commandes » sur Android 14.','2026-04-22 18:10:16','2026-04-23 01:23:16',12,11,7,7,3,4),(26,'Application métier inaccessible','L\'application est inaccessible depuis l\'ouverture des bureaux. Un message d\'erreur 503 s\'affiche lors de la connexion.','2026-04-23 08:58:07','2026-04-25 11:47:07',6,7,17,2,3,4),(27,'Partages réseau inaccessibles (Serveur de fichiers)','Les partages réseau au service RH sont inaccessibles depuis hier soir. Les utilisateurs obt